package com.hrflow.controller; import com.hrflow.entity.*;import com.hrflow.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*; @RestController @RequestMapping("/api/attendance") @RequiredArgsConstructor public class AttendanceController{final AttendanceRepository r;@GetMapping public List<Attendance> all(@RequestParam(required=false)Long employeeId){return employeeId==null?r.findAll():r.findByEmployeeIdOrderByAttendanceDateDesc(employeeId);}@PostMapping("/check-in/{employeeId}") public Attendance in(@PathVariable Long employeeId,@RequestParam(defaultValue="OFFICE")String location){LocalDate d=LocalDate.now();if(r.findByEmployeeIdAndAttendanceDate(employeeId,d).isPresent())throw new IllegalStateException("Already checked in today");Attendance a=new Attendance();a.setEmployeeId(employeeId);a.setAttendanceDate(d);a.setCheckIn(LocalDateTime.now());a.setStatus(AttendanceStatus.PRESENT);a.setLocation(location);return r.save(a);}@PostMapping("/check-out/{employeeId}") public Attendance out(@PathVariable Long employeeId){Attendance a=r.findByEmployeeIdAndAttendanceDate(employeeId,LocalDate.now()).orElseThrow(()->new IllegalStateException("Check in first"));if(a.getCheckOut()!=null)throw new IllegalStateException("Already checked out");a.setCheckOut(LocalDateTime.now());a.setWorkingMinutes((int)ChronoUnit.MINUTES.between(a.getCheckIn(),a.getCheckOut()));return r.save(a);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")public Attendance update(@PathVariable Long id,@RequestBody Attendance x){x.setId(id);return r.save(x);}}
